class PR18RunMetadataRepairTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        managed.PR18ManagedOwnerRepairTests.setUpClass()
        cls.historical = managed.PR18ManagedOwnerRepairTests
        cls.collector_before, cls.collector_after = {}, {}
        if len(COLLECTOR_INPUTS) != 5:
            raise AssertionError("closed independent five-path collector/fixture input")
        for path, pair in COLLECTOR_INPUTS.items():
            for target, (size, digest, encoded) in zip(
                    (cls.collector_before, cls.collector_after), pair, strict=True):
                raw = base64.b64decode(encoded, validate=True)
                if len(raw) != size or hashlib.sha256(raw).hexdigest() != digest:
                    raise AssertionError("independent collector input identity")
                target[path] = raw.decode("utf-8")
        wrapper = Path(managed.__file__).read_bytes()
        if hashlib.sha256(wrapper).hexdigest() != MANAGED_WRAPPER_SHA256:
            raise AssertionError("historical managed wrapper identity")
        cls.policy_input = Path(sc.__file__).read_bytes()
        cls.before = {**cls.collector_before,
                      POLICY: cls.historical.policy_input.decode(),
                      MANAGED_TEST: managed._historical_managed_input(MANAGED_TEST).decode(),
                      TEST: None}
        cls.after = {**cls.collector_after, POLICY: cls.policy_input.decode(),
                     MANAGED_TEST: wrapper.decode(),
                     TEST: Path(__file__).read_text(encoding="utf-8")}
        if len(cls.before) != 8 or set(cls.before) != set(cls.after):
            raise AssertionError("closed independent eight-path repair")

    def setUp(self):
        temp = tempfile.TemporaryDirectory()
        self.addCleanup(temp.cleanup)
        self.repo = support.TempRepo(Path(temp.name) / "repo")
        h = self.historical
        files = {**h.old.anchor_fixture.before, **h.old.repair_before}
        earlier = set(h.old.anchor_fixture.SOURCE) | set(h.old.repair_after)
        for path, value in h.fixture["before"].items():
            if path not in earlier and value is not None:
                files[path] = value
        for path, value in self.collector_before.items():
            if path not in earlier and path not in h.after:
                files[path] = value
        self.base = self.repo.commit(files, "independent historical inputs")
        self.anchor = self.repo.commit(h.old.anchor_fixture.after, "exact observer31")
        self.repaired = self.repo.commit(h.old.repair_after, "exact verification38")
        self.managed = self.repo.commit(h.after, "exact historical managed12")
        for path, value in self.before.items():
            dest = self.repo.root / path
            self.assertEqual(dest.read_text(encoding="utf-8") if dest.is_file() else None, value)

    def head(self, extra=None):
        self.repo.checkout(self.managed)
        return self.repo.commit({**self.after, **(extra or {})}, "one exact run-metadata repair")

    def local_refuses(self, head, base=None):
        base = base or self.managed
        self.assertIn("pr18-run-metadata-repair-incomplete", sc.check_ci_source(self.repo.root, base, head))
        self.assertIn("classifier-v2-invalid:pr18-run-metadata-repair",
                      sc.classify_v2(self.repo.root, base, head).reasons)

    def full_refuses(self, head):
        self.assertTrue(sc.check_ci_source(self.repo.root, self.base, head))
        self.assertIn("migration-call:cmd/whatomate/main.go",
                      sc.classify_v2(self.repo.root, self.base, head).reasons)

    def test_exact_local_and_full_origin_keep_distinct_results(self):
        head = self.head()
        legacy = sc.classify(self.repo.root, self.managed, head)
        self.assertEqual((legacy.kind, legacy.dormant, legacy.reasons), ("none", False, ()))
        local = sc.classify_v2(self.repo.root, self.managed, head)
        self.assertEqual((local.kind, local.dormant, local.reasons, local.migration_changes),
                         ("none", False, (), ()))
        full = sc.classify_v2(self.repo.root, self.base, head)
        self.assertEqual((full.kind, full.dormant, full.reasons), ("data", True, ()))
        self.assertEqual(full.migration_changes, self.historical.old.anchor_fixture.MIGRATION_OBSERVATIONS)
        for base in (self.managed, self.base):
            self.assertEqual(sc.check_ci_source(self.repo.root, base, head), ())
        self.assertEqual(local.requirements, ("compat-required", "generated-migration-closure-ci"))
        self.assertEqual(full.requirements, local.requirements)

    def test_every_missing_row_and_corrupted_postimage_refuses(self):
        for path in self.after:
            with self.subTest(path=path, mutation="missing"):
                head = self.head({path: self.before[path]})
                self.local_refuses(head); self.full_refuses(head)
            with self.subTest(path=path, mutation="changed"):
                head = self.head({path: self.after[path] + "\n# unreviewed\n"})
                self.local_refuses(head); self.full_refuses(head)

    def test_split_multiple_extra_prefix_suffix_and_reapply_refuse(self):
        path = "release/deployment/compat_collect.py"
        self.repo.commit({path: self.after[path]}, "partial")
        head = self.repo.commit(self.after, "remaining")
        self.local_refuses(head); self.full_refuses(head)
        head = self.head({"README.md": "unreviewed extra\n"})
        self.local_refuses(head); self.full_refuses(head)
        self.repo.checkout(self.managed)
        self.repo.commit({"README.md": "nonempty prefix\n"})
        head = self.repo.commit(self.after, "repair after prefix")
        self.local_refuses(head); self.full_refuses(head)
        self.head()
        head = self.repo.commit({"README.md": "nonempty suffix\n"})
        self.local_refuses(head); self.full_refuses(head)
        self.head()
        self.repo.commit(self.before, "undo whole repair")
        head = self.repo.commit(self.after, "repeat whole repair")
        self.local_refuses(head); self.full_refuses(head)

    def test_complete_undo_cannot_escape_net_zero_guard(self):
        self.head()
        head = self.repo.commit(self.before, "complete undo")
        self.assertEqual(self.repo.git("diff", "--name-only", self.managed, head), "")
        self.local_refuses(head); self.full_refuses(head)

    def test_bounded_noop_prefix_and_suffix_remain_allowed(self):
        self.repo.git("commit", "--allow-empty", "-m", "prefix noop")
        self.repo.commit(self.after, "exact edge after noop")
        self.repo.git("commit", "--allow-empty", "-m", "suffix noop")
        head = self.repo.git("rev-parse", "HEAD").strip()
        self.assertEqual(sc.check_ci_source(self.repo.root, self.managed, head), ())
        self.assertEqual(sc.check_ci_source(self.repo.root, self.base, head), ())
        self.assertFalse(sc.classify_v2(self.repo.root, self.base, head).reasons)

    def test_wrong_mode_and_renamed_input_refuse(self):
        for path, value in self.after.items():
            dest = self.repo.root / path
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(value, encoding="utf-8", newline="\n")
        # Match the committed executable bit in the working tree on POSIX;
        # Windows ignores executable chmod and Git's native filemode handling
        # still permits the explicit index-mode negative without dirty checkout.
        (self.repo.root / TEST).chmod(0o755)
        self.repo.git("add", "-A")
        self.repo.git("update-index", "--chmod=+x", TEST)
        self.repo.git("commit", "-m", "wrong executable mode")
        head = self.repo.git("rev-parse", "HEAD").strip()
        self.local_refuses(head); self.full_refuses(head)
        head = self.head({TEST: None, TEST + ".renamed": self.after[TEST]})
        self.local_refuses(head); self.full_refuses(head)

    def test_protected_catalog_pending_and_descriptor_changes_refuse(self):
        for path in ("internal/dbcatalog/registry/data_steps.json", "internal/dbcatalog/golden/seeds.json",
                     "internal/dbcatalog/dormant_entrypoints.json", sc.CATALOG):
            self.repo.checkout(self.managed)
            value = (self.repo.root / path).read_text(encoding="utf-8") + "\n"
            head = self.head({path: value})
            self.local_refuses(head); self.full_refuses(head)
        for path in (sc._V2_PENDING + "unreviewed.json", sc.schema_nullable.SOURCE_PATH):
            head = self.head({path: "{}\n"})
            self.local_refuses(head)
            self.assertTrue(sc.check_ci_source(self.repo.root, self.base, head))
            self.assertTrue(sc.classify_v2(self.repo.root, self.base, head).reasons)

    def test_new_policy_slot_does_not_self_authorize_changed_bytes(self):
        match, = SLOT.finditer(self.policy_input)
        body = self.policy_input + b"\n# unreviewed consumer change\n"
        canonical = body[:match.start(1)] + b"0" * 64 + body[match.end(1):]
        recomputed = body[:match.start(1)] + hashlib.sha256(canonical).hexdigest().encode() + body[match.end(1):]
        for value in (body, recomputed, self.policy_input + match.group(0),
                      self.policy_input[:match.start(1)] + b"f" * 64 + self.policy_input[match.end(1):],
                      self.historical.policy_input):
            with self.subTest(digest=hashlib.sha256(value).hexdigest()):
                head = self.head({POLICY: value.decode()})
                self.local_refuses(head); self.full_refuses(head)

    def test_incomplete_or_reordered_predecessors_refuse_full_origin(self):
        for base in (self.base, self.anchor, self.repaired):
            self.repo.checkout(base)
            head = self.repo.commit(self.after, "metadata repair before managed")
            if base == self.base:
                self.assertEqual(sc.check_ci_source(self.repo.root, self.base, head),
                                 ("pr18-run-metadata-repair-incomplete",))
                self.assertEqual(sc.classify_v2(self.repo.root, self.base, head).reasons,
                                 ("classifier-v2-invalid:pr18-run-metadata-repair",))
            else:
                self.full_refuses(head)
        self.repo.checkout(self.repaired)
        self.repo.commit(self.after, "metadata before managed")
        head = self.repo.commit(self.historical.after, "managed after metadata")
        self.full_refuses(head)

    def test_invalid_marker_introduction_then_undo_cannot_hide_in_clean_delta(self):
        for introduced in (self.after, {TEST: self.after[TEST]}):
            with self.subTest(paths=tuple(sorted(introduced))):
                self.repo.checkout(self.base)
                original = {path: ((self.repo.root / path).read_text(encoding="utf-8")
                                   if (self.repo.root / path).is_file() else None)
                            for path in introduced}
                self.repo.commit(introduced, "illegal marker introduction")
                head = self.repo.commit(original, "undo illegal introduction")
                self.assertEqual(self.repo.git("diff", "--name-only", self.base, head), "")
                self.assertEqual(sc.check_ci_source(self.repo.root, self.base, head),
                                 ("pr18-run-metadata-repair-incomplete",))
                self.assertEqual(sc.classify_v2(self.repo.root, self.base, head).reasons,
                                 ("classifier-v2-invalid:pr18-run-metadata-repair",))

    def test_marker_scope_preserves_completed_base_and_unmarked_second_parent(self):
        base = self.head()
        head = self.repo.commit({TEST: self.after[TEST] + "\n# ordinary later test edit\n"})
        self.assertEqual(sc.check_ci_source(self.repo.root, base, head), ())
        policy = sc.classify_v2(self.repo.root, base, head)
        self.assertEqual((policy.kind, policy.dormant, policy.reasons, policy.migration_changes),
                         ("none", False, (), ()))
        self.full_refuses(head)
        self.repo.git("checkout", "-b", "ordinary-marker-free-side", self.base)
        side = self.repo.commit({"README.side": "ordinary side\n"})
        self.repo.git("checkout", "-b", "ordinary-marker-free-main", self.base)
        self.repo.commit({"README.main": "ordinary main\n"})
        self.repo.git("merge", "--no-ff", side, "-m", "ordinary second-parent comparison")
        head = self.repo.git("rev-parse", "HEAD").strip()
        self.assertEqual(sc.check_ci_source(self.repo.root, side, head), ())
        self.assertFalse(sc.classify_v2(self.repo.root, side, head).reasons)

    def test_marker_history_memo_is_success_only_and_keeps_real_reader_deadline(self):
        self.repo.checkout(self.base)
        ordinary = self.repo.commit({"README.md": "ordinary source with no marker history\n"})
        original = sc._pr18_verification_repair_history
        reader = source_git.ImmutableGit(self.repo.root, Path(shutil.which("git")))
        repository = sc._Repository(self.repo.root)
        with mock.patch.object(sc, "_git", wraps=sc._git) as git:
            with reader.operation():
                self.assertFalse(sc._pr18_run_metadata_changed(repository, self.base, ordinary))
                self.assertFalse(sc._pr18_run_metadata_changed(repository, self.base, ordinary))
                scans = [call for call in git.call_args_list
                         if call.args[1][:3] == ["rev-list", "--first-parent", "--reverse"]]
                self.assertEqual(len(scans), 1)
        self.assertTrue(reader.closed)
        self.assertFalse(reader.failed)
        self.repo.checkout(self.base)
        invalid = self.repo.commit({TEST: self.after[TEST]}, "marker without predecessor")
        reader = source_git.ImmutableGit(self.repo.root, Path(shutil.which("git")))
        repository = sc._Repository(self.repo.root)
        with mock.patch.object(sc, "_pr18_verification_repair_history", wraps=original) as history:
            with reader.operation():
                for _ in range(2):
                    with self.assertRaises(sc._Invalid):
                        sc._pr18_run_metadata_changed(repository, self.base, invalid)
                self.assertEqual(history.call_count, 2)
        self.assertTrue(reader.closed)
        self.assertFalse(reader.failed)
        clock = [100.0]
        reader = source_git.ImmutableGit(self.repo.root, Path(shutil.which("git")), clock=lambda: clock[0])
        repository = sc._Repository(self.repo.root)
        with self.assertRaises(source_git.SourceGitRefusal):
            with reader.operation():
                self.assertFalse(sc._pr18_run_metadata_changed(repository, self.base, ordinary))
                clock[0] = reader.deadline
                sc._pr18_run_metadata_changed(repository, self.base, ordinary)
        self.assertTrue(reader.closed and reader.failed)

    def test_wrong_preimage_and_preexisting_new_file_fail_exact_edge_proof(self):
        for path, value in (("release/deployment/compat_rollback_collect.py", "# wrong preimage\n"),
                            (TEST, "# preexisting test\n")):
            self.repo.checkout(self.managed)
            wrong_base = self.repo.commit({path: value}, "wrong predecessor")
            head = self.repo.commit(self.after, "otherwise exact repair")
            with self.assertRaises(sc._Invalid):
                sc._pr18_run_metadata_local(sc._Repository(self.repo.root), wrong_base, head)
            self.full_refuses(head)

    def test_second_parent_base_does_not_prove_first_parent_lineage(self):
        self.repo.git("checkout", "-b", "metadata-side", self.managed)
        self.repo.git("commit", "--allow-empty", "-m", "side")
        side = self.repo.git("rev-parse", "HEAD").strip()
        self.repo.git("checkout", "-b", "metadata-main", self.managed)
        self.repo.commit(self.after, "exact edge")
        self.repo.git("merge", "--no-ff", side, "-m", "side merged")
        head = self.repo.git("rev-parse", "HEAD").strip()
        self.local_refuses(head, side)

    def test_original_deadline_and_history_limits_remain_effective(self):
        head = self.head()
        for call in (sc.check_ci_source, sc.classify_v2):
            clock = [100.0]
            reader = source_git.ImmutableGit(self.repo.root, Path(shutil.which("git")), clock=lambda: clock[0])
            with self.assertRaises(source_git.SourceGitRefusal):
                with reader.operation():
                    clock[0] = reader.deadline
                    call(self.repo.root, self.managed, head)
            self.assertTrue(reader.failed and reader.closed)
        original = sc._git
        def huge(root, args):
            if args[:3] == ["rev-list", "--first-parent", "--reverse"]:
                return (b"a" * 40 + b"\n") * (sc.MAX_HISTORY_COMMITS + 1)
            return original(root, args)
        with mock.patch.object(sc, "_git", side_effect=huge):
            # The original legacy bound owns this refusal before the new guard.
            self.assertEqual(sc.check_ci_source(self.repo.root, self.managed, head),
                             ("classifier-invalid:migration-path",))
            self.assertEqual(sc.classify_v2(self.repo.root, self.managed, head).reasons,
                             ("classifier-invalid:migration-path",
                              "classifier-v2-invalid:migration-path"))

    def test_oversized_collector_retains_original_blob_cap(self):
        head = self.head({"release/deployment/compat_collect.py": " " * (sc.MAX_ARTIFACT_BYTES + 1)})
        self.local_refuses(head)
        self.full_refuses(head)

    def test_resolver_proves_full_origin_and_rejects_unrelated_suffix(self):
        head = self.head()
        latest = SimpleNamespace(record_sha=self.managed,
            live=SimpleNamespace(origin_source=SimpleNamespace(sha=self.base)))
        def resolve(candidate):
            reader = source_git.ImmutableGit(self.repo.root, Path(shutil.which("git")))
            with reader.operation():
                value = record_resolver._forward_source(reader, self.repo.root, latest, SimpleNamespace(sha=candidate))
            self.assertTrue(reader.closed)
            return value
        value = resolve(head)
        self.assertEqual(value[3], self.base)
        self.assertEqual((value[1].kind, value[1].dormant, value[1].reasons), ("data", True, ()))
        later = self.repo.commit({"README.md": "ordinary local none is not full-origin admission\n"})
        self.assertEqual(sc.check_ci_source(self.repo.root, head, later), ())
        self.assertIn("migration-call:cmd/whatomate/main.go", resolve(later)[1].reasons)


class RunMetadataHistoryReuseTests(unittest.TestCase):
    """Small read-custody regressions; the real historical cases remain above."""
    def test_retained_history_avoids_added_scan_and_unrelated_before_probe(self):
        base, head = "a" * 40, "b" * 40
        repository = sc._Repository(Path("unused-static-history-fixture"))
        raw = (head + "\n").encode()
        sc._pr18_run_metadata_remember_history(repository, base, head, raw)
        marker = next(path for path, (old, _) in sc._PR18_RUN_METADATA_REPAIR_FILES.items() if old is None)
        with mock.patch.object(repository, "_tree", return_value=b"") as tree, \
                mock.patch.object(sc, "_git", return_value=b"commit\n") as git, \
                mock.patch.object(sc, "_pr18_run_metadata_before") as before:
            self.assertFalse(sc._pr18_run_metadata_changed(repository, base, head))
        before.assert_not_called()
        git.assert_called_once_with(repository.root, ["cat-file", "-t", base])
        self.assertIn(mock.call(head, marker), tree.call_args_list)
        self.assertEqual(repository._run_metadata_history_reads[(base, head)], raw)
        marked = sc._Repository(Path("unused-static-history-fixture"))
        marked._trees[(base, marker)] = b"present"
        with mock.patch.object(sc, "_git", side_effect=source_git.SourceGitRefusal("git-failed:source-budget")) as git:
            with self.assertRaises(source_git.SourceGitRefusal):
                sc._pr18_run_metadata_changed(marked, base, head)
        git.assert_called_once_with(marked.root, ["cat-file", "-t", base])
        self.assertFalse(getattr(marked, "_run_metadata_introductions_checked", set()))

    def test_retained_history_keeps_invalid_introduction_and_undo_visible(self):
        base, introduced, head = "a" * 40, "b" * 40, "c" * 40
        repository = sc._Repository(Path("unused-static-history-fixture"))
        raw = (introduced + "\n" + head + "\n").encode()
        sc._pr18_run_metadata_remember_history(repository, base, head, raw)
        marker = next(path for path, (old, _) in sc._PR18_RUN_METADATA_REPAIR_FILES.items() if old is None)
        def tree(revision, path):
            return b"present" if (revision, path) == (introduced, marker) else b""
        with mock.patch.object(repository, "_tree", side_effect=tree), \
                mock.patch.object(sc, "_git", return_value=b"commit\n"), \
                mock.patch.object(sc, "_pr18_verification_repair_history",
                                  return_value=((base, introduced), (introduced, head))) as history, \
                mock.patch.object(sc, "_pr18_run_metadata_edge", side_effect=sc._Invalid) as edge:
            for _ in range(2):
                with self.assertRaises(sc._Invalid):
                    sc._pr18_run_metadata_changed(repository, base, head)
        self.assertEqual(history.call_count, 2)
        self.assertEqual(edge.call_args_list, [mock.call(repository, base, introduced)] * 2)
        self.assertNotIn((base, head), getattr(repository, "_run_metadata_introductions_checked", set()))

    def test_read_memo_rejects_mutable_malformed_oversized_and_conflicting_ranges(self):
        base, head = "a" * 40, "b" * 40
        repository = sc._Repository(Path("unused-static-history-fixture"))
        for left, right, raw in (("HEAD", head, (head + "\n").encode()),
                                 (base, "main", (head + "\n").encode()),
                                 (base, head, b"not-an-oid\n"),
                                 (base, head, (head + "\n").encode() * (sc.MAX_HISTORY_COMMITS + 1)),
                                 (base, head, (head + "\n" + head + "\n").encode()),
                                 (base, head, b"")):
            sc._pr18_run_metadata_remember_history(repository, left, right, raw)
            self.assertFalse(getattr(repository, "_run_metadata_history_reads", {}))
        raw = (head + "\n").encode()
        sc._pr18_run_metadata_remember_history(repository, base, head, raw)
        with self.assertRaises(sc._Invalid):
            sc._pr18_run_metadata_remember_history(repository, base, head,
                                                 (("c" * 40) + "\n" + head + "\n").encode())
        self.assertEqual(repository._run_metadata_history_reads, {(base, head): raw})


